<?php
require dirname(__DIR__).'/app/bootstrap.php';require_permission('reports.view');require dirname(__DIR__).'/app/layout.php';require dirname(__DIR__).'/app/reports.php';$type=$_GET['report']??'';[$start,$end]=period();$actions='<button class="btn" data-print>'.icon('printer').' Print report</button>';if($type&&can('reports.export'))$actions.='<a class="btn primary" href="export.php?'.e(http_build_query(array_merge($_GET,['module'=>'report']))).'">'.icon('download').' Export CSV</a>';page_start('Reports','Clear numbers. Meaningful insights. Better decisions.',$actions);
?><div class="section-toolbar"><h2><?= e(report_definitions()[$type][0]??'Your business, in focus') ?></h2><form class="period-form"><input type="hidden" name="report" value="<?= e($type) ?>"><?php period_select(); ?></form></div><?php if($type&&isset(report_definitions()[$type])):$data=report_data($type,$start,$end);$page=max(1,(int)($_GET['page']??1));$count=count($data);$display=array_slice($data,($page-1)*25,25);?><section class="panel"><div class="panel-head"><div><h2><?= e(report_definitions()[$type][0]) ?></h2><p><?= date_label($start) ?> – <?= date_label($end) ?> · Asia/Kolkata · INR</p></div><a class="btn small" href="reports.php">All reports</a></div><div class="table-scroll report-table"><table><thead><tr><?php foreach(array_keys($data[0]??[]) as $key): ?><th><?= e(strtoupper(str_replace('_',' ',$key))) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($display as $r): ?><tr><?php foreach($r as $k=>$v): ?><td><?= e(in_array($k,['billed','amount','total','paid','outstanding','invoiced_revenue','recorded_expenses','deal_value','quoted_value'],true)?money($v):$v) ?></td><?php endforeach; ?></tr><?php endforeach;if(!$display): ?><tr><td class="empty">No records for this period.</td></tr><?php endif; ?></tbody></table></div><div class="table-foot"><span><?= $count ?> rows · Page <?= $page ?></span><div class="pagination"><?php if($page>1): ?><a class="btn" href="?<?= e(http_build_query(array_merge($_GET,['page'=>$page-1]))) ?>">Previous</a><?php endif;if($page*25<$count): ?><a class="btn" href="?<?= e(http_build_query(array_merge($_GET,['page'=>$page+1]))) ?>">Next</a><?php endif; ?></div></div></section><?php else: ?><div class="report-grid"><?php foreach(report_definitions() as $key=>[$name,$description,$ic]):$needed=match($key){'revenue','invoices','outstanding','aging'=>'invoices.view','activity'=>'managers.manage','summary'=>'dashboard.view',default=>$key.'.view'};if(!can($needed))continue; ?><a href="reports.php?report=<?= $key ?>" class="panel report-card"><?= icon($ic) ?><h2><?= e($name) ?></h2><p><?= e($description) ?></p><span class="btn link">Open report <?= icon('arrow-right') ?></span></a><?php endforeach; ?></div><?php endif;page_end(); ?>
